import heapq

def match(orders):
    buy_heap = []   # max-heap via negative price: (-price, arrival, id)
    sell_heap = []  # min-heap: (price, arrival, id)
    seq = 0
    book = {}  # id -> {'side','price','remaining','active'}
    trades = []

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book and book[oid]['active'] and book[oid]['remaining'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        remaining = qty
        seq += 1
        arrival = seq

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            if side == 'buy':
                p, s, oid2 = top
            else:
                negp, s, oid2 = top
                p = -negp

            # check if resting order still valid
            if oid2 not in book or not book[oid2]['active'] or book[oid2]['remaining'] <= 0:
                heapq.heappop(opp_heap)
                continue

            # price condition check (skip for market orders)
            if typ != 'market':
                if side == 'buy' and p > price:
                    break
                if side == 'sell' and p < price:
                    break

            resting = book[oid2]
            trade_qty = min(remaining, resting['remaining'])

            if side == 'buy':
                trades.append([oid, oid2, p, trade_qty])
            else:
                trades.append([oid2, oid, p, trade_qty])

            remaining -= trade_qty
            resting['remaining'] -= trade_qty

            if resting['remaining'] == 0:
                resting['active'] = False
                heapq.heappop(opp_heap)
            # else: resting order still has qty left, incoming remaining must be 0, loop will end

        if typ == 'limit':
            if remaining > 0:
                book[oid] = {'side': side, 'price': price, 'remaining': remaining, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, arrival, oid))
                else:
                    heapq.heappush(sell_heap, (price, arrival, oid))
            else:
                book[oid] = {'side': side, 'price': price, 'remaining': 0, 'active': False}
        # ioc and market: discard remainder, do not rest in book

    return trades

